const BASE_ID = 'appdB6Amrw3JWFCUH'; // * להחליף ב-Base ID האמיתי
const VAT_RATE = 0.18; // מע"מ ישראלי 18%

const rec = $json;
const fields = rec.fields || {};
const amount = Number(fields.Amount) || 0;
const vat = Math.round(amount * VAT_RATE * 100) / 100;
const total = Math.round(amount * (1 + VAT_RATE) * 100) / 100;
// אם אין עדיין סטטוס (שדה טקסט חופשי, לא אכוף על ידי Airtable) — נקבע pending
const status = (fields.Status && fields.Status.trim()) ? fields.Status : 'pending';

return [{
  json: {
    recordId: rec.id,
    url: `https://api.airtable.com/v0/${BASE_ID}/Invoices/${rec.id}`,
    body: { fields: { VatAmount: vat, Total: total, Status: status } }
  }
}];
